def bfs_4_through_8(grid, height, width):
    """BFS 4-connected through cells, but consider 8-connectivity for neighbors"""
    dist = {}
    for r in range(height):
        for c in range(width):
            dist[(r,c)] = 999999

    # Start from all 5s
    queue = deque([(r, c) for r in range(height) for c in range(width) if grid[r][c] == 5])
    for r, c in queue:
        dist[(r,c)] = 0

    def get_8_neighbors(r, c, height, width):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < height and 0 <= nc < width:
                    yield (nr, nc)

    while queue:
        r, c = queue.popleft()
        for nr, nc in get_8_neighbors(r, c, height, width):
            if dist[(nr,nc)] == 999999:
                dist[(nr,nc)] = dist[(r,c)] + 1
                queue.append((nr, nc))

    return dist

